<script setup lang="ts">
import { unwrap } from '~/api/client'; import { displayError } from '~/utils/errors';
const api = useMarketplaceApi(); const route = useRoute(); const token = ref(typeof route.query.token === 'string' ? route.query.token : ''); const password = ref(''); const confirmation = ref(''); const pending = ref(false); const message = ref(''); const error = ref(''); const show = ref(false);
async function submit() { error.value = ''; if (password.value !== confirmation.value) { error.value = 'Konfirmasi password tidak sama.'; return; } pending.value = true; try { message.value = unwrap(await api.POST('/auth/reset-password', { body: { token: token.value, password: password.value } })).message; } catch (cause) { error.value = displayError(cause).message; } finally { pending.value = false; } }
useSeoMeta({ title: 'Atur password baru — Niaga' });
</script>
<template><main id="main-content" class="auth-shell"><section v-if="message" class="auth-card"><p class="eyebrow">Password diperbarui</p><h1>Anda dapat masuk kembali</h1><p class="success">{{ message }}</p><NuxtLink class="button" to="/login">Masuk</NuxtLink></section><form v-else class="auth-card" @submit.prevent="submit"><p class="eyebrow">Pemulihan akun</p><h1>Atur password baru</h1><label class="form-field">Token<input v-model.trim="token" required autocomplete="off"></label><label class="form-field">Password baru<div class="input-action"><input v-model="password" required :type="show ? 'text' : 'password'" minlength="12" autocomplete="new-password"><button type="button" @click="show = !show">{{ show ? 'Sembunyi' : 'Lihat' }}</button></div></label><label class="form-field">Ulangi password<input v-model="confirmation" required :type="show ? 'text' : 'password'" minlength="12" autocomplete="new-password"></label><p v-if="error" class="error" role="alert">{{ error }}</p><button :disabled="pending || !token || password.length < 12 || password !== confirmation" type="submit">{{ pending ? 'Menyimpan…' : 'Simpan password' }}</button></form></main></template>
